const why = {
	fix: `<strong class="badge">Per correggere</strong> `,

	buttons: `<div class="why"><p>Suggerimento: il nome accessibile di un pulsante deve chiarire cosa farà quando viene cliccato. Se l’azione cambia, lo stato attuale deve essere chiaro:</p><ul><li>Pulsanti che aggiornano l’etichetta:<br>“Riproduci/Pausa”, “Mostra dettagli/Nascondi dettagli”</li><li>Pulsanti che <a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/button_role#associated_aria_roles_states_and_properties">aggiornano lo stato</a>:<br>“Riproduci/Riproduci, premuto”, “Dettagli, compresso/Dettagli, espanso”.</li></ul></div>`,

	headings: `<div class="why"><p>Suggerimento: intestazioni e sotto-intestazioni organizzano i contenuti in una struttura gerarchica. Gli utenti di lettori di schermo si affidano a questa struttura per comprendere ed esplorare le pagine:</p>
<ul><li>Intestazione di livello 1: titoli di pagina
<ul><li>Intestazione di livello 2: argomenti principali
<ul><li>Intestazione di livello 3: sotto-argomenti</li></ul></li></ul></li></ul></div>`,

	images: `<div class="why"><p>Suggerimento: quando scrivi un testo alternativo, descrivi ciò che l’immagine <em>significa</em> nel contesto, non solo ciò che mostra. Per esempio, una foto di una bambina che calcia un pallone può significare:</p>
<ul><li>Hanno giocato sotto la pioggia battente.</li>
<li>Le nuove divise della squadra hanno dei fantastici loghi con draghi.</li>
<li>Ha segnato il gol della vittoria dalla fascia sinistra!</li></ul></div>`,

	links: `<div class="why"><p>Suggerimento: chi legge scansiona la pagina tramite i link e usa la ricerca nella pagina per trovarli per nome, quindi i link devono essere significativi, unici e concisi:</p><ul><li>Ideale: “Scopri di più sui <a href="https://webaim.org/techniques/hypertext/link_text">link significativi</a>”</li><li>Non unico: “Clicca <a href="https://webaim.org/techniques/hypertext/link_text">qui</a> per saperne di più sui link significativi.”</li><li>Non conciso: “<a href="https://webaim.org/techniques/hypertext/link_text">Clicca qui per saperne di più sui link significativi</a>”</li></ul></div>`,

	imageLinks: `<div class="why"><p>Suggerimento: il testo alternativo deve descrivere ciò che l’immagine significa, non ciò che contiene. Per un’immagine usata come link, il significato è la destinazione del link:</p><ul><li>“<em>Lente d’ingrandimento</em>” descrive l’immagine, non il link.</li><li>“<em>Lente d’ingrandimento cerca</em>” descrive in modo confuso entrambi.</li><li>“<em>Cerca</em>” descrive correttamente la destinazione del link.</li></ul></div>`,
};

export const tips = {
	ALT_FILE_EXT: `<p><span hidden>%(alt)</span><strong>Testo alternativo:</strong> <i>%(ALT_TEXT)</i></p><p>I lettori di schermo proveranno a pronunciare questo URL, spesso una lettera alla volta. Probabilmente questo non trasmette lo stesso significato che si ha vedendo l’immagine.</p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	ALT_MAYBE_BAD: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	ALT_MAYBE_BAD_WARNING: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	ALT_PLACEHOLDER: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	ALT_UNPRONOUNCEABLE: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>Questo testo alternativo contiene solo simboli o spazi non pronunciabili. I lettori di schermo annunceranno la presenza di un’immagine e poi faranno una pausa imbarazzante o diranno qualcosa di incomprensibile.</p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	ARIA_INPUT_FIELD_NAME: `<p><strong>Elemento:</strong> <code>%(EL)</code></p><p>${why.fix}Fornisci un’etichetta valida; per gli elementi di input personalizzati questo significa spesso testo interno oppure un attributo title, aria-label o aria-labelledby.</p>`,
	BTN_EMPTY: `<p>${why.fix}Usa un qualsiasi metodo valido per indicare ai lettori di schermo cosa fa questo pulsante, ad esempio un testo, un testo alternativo su un’icona o un attributo title.</p>`,
	BTN_EMPTY_LABELLEDBY: `<p>Questo pulsante ha un valore <code>aria-labelledby</code> vuoto o che non corrisponde al valore <code>ID</code> di un altro elemento della pagina.</p><p>${why.fix}Ricollega l’ID a un elemento della pagina, oppure rimuovi questo attributo e descrivi il pulsante in un altro modo.</p>`,
	BTN_TIP: `${why.buttons}`,
	BTN_ROLE_IN_NAME: `<p><strong>Etichetta per i lettori di schermo:</strong> <i>%(TEXT)</i></p><p>I lettori di schermo usano la parola “pulsante” per annunciare che stanno descrivendo un pulsante; questa parola è quindi ripetitiva.</p><p>${why.fix}L’etichetta del pulsante deve corrispondere alla sua azione. Se l’etichetta visibile è un’icona anziché un testo, etichetta il pulsante con il significato dell’icona, ad esempio “Riproduci”, “Cerca” o “Menu”.</p>`,
	BTN_UNPRONOUNCEABLE: `<p><strong>Testo del pulsante:</strong> <i>%(TEXT)</i></p><p>${why.fix}Aggiungi testo, un titolo o un aria-label che descriva cosa fa.</p><div class="why"><p>Suggerimento: i lettori di schermo non possono descrivere i pulsanti che contengono solo spazi o simboli. Rimangono silenziosi (“Pulsante, [...pausa imbarazzante dove dovrebbe essere l’etichetta del pulsante...]”), oppure leggono il nome del simbolo.</p></div>`,
	CONTRAST_WARNING: `Un’immagine di sfondo o un gradiente impediscono a questo strumento di determinare con certezza il colore dietro al testo. Usa il selettore di colore qui sotto per verificarlo manualmente.`,
	DUPLICATE_ID: `<p>In questa pagina gli ID sono usati per etichette o destinazioni di link, quindi devono essere unici.</p><p>${why.fix}Modifica questo ID: <code>#%(ID)</code></p><div class="why"><p>Nella maggior parte dei CMS, questo valore proviene da un campo chiamato “name” o “id” nelle proprietà dell’elemento. In HTML è un attributo: <code>&lt;a id="MIO-ID"&gt;</code></p></div>`,
	DUPLICATE_TITLE: `<p>${why.fix}Elimina il testo del link o l’attributo <code>title</code>.</p><div class="why"><p>Suggerimento: i tooltip <code>title</code> appaiono solo al passaggio del mouse. Non sono visibili quando si naviga da telefono o con la tastiera, quindi molti utenti non li vedranno mai. Non dovrebbero mai contenere informazioni uniche o importanti.</p></div>`,
	EMBED_AUDIO: `<p>Questo controllo non è in grado di verificare se un lettore audio dispone di una trascrizione, né se la trascrizione è accurata.</p><p>${why.fix}Assicurati che sia disponibile una <a href="https://www.w3.org/WAI/media/av/transcribing/">trascrizione o alternativa testuale</a>, e verifica che i parlanti e gli effetti sonori significativi siano identificati correttamente.</p>`,
	EMBED_DATA_VIZ: `<p>I widget di visualizzazione incorporati sono spesso difficili o impossibili da usare con le tecnologie assistive, possono risultare difficili da comprendere per chi ha ipovisione o daltonismo e possono richiedere un ampio scorrimento orizzontale sui telefoni.</p><p>${why.fix}A meno che questo contenuto incorporato non abbia un elevato contrasto visivo, possa essere usato da tastiera <strong><em>e</em></strong> descritto da un lettore di schermo, aggiungi un formato alternativo equivalente, come una descrizione testuale, una tabella di dati o un foglio di calcolo scaricabile.</p>`,
	EMBED_GENERAL: `I controlli automatici non possono esaminare il contenuto degli elementi incorporati. Assicurati che qualcuno abbia verificato che tutte le immagini al loro interno abbiano un testo alternativo, che i video abbiano i sottotitoli, che il testo abbia contrasto sufficiente e che link e pulsanti siano <a href="https://webaim.org/techniques/keyboard/">accessibili da tastiera</a>.`,
	EMBED_MISSING_TITLE: `<p>Gli elementi incorporati necessitano di un nome accessibile che ne descriva il contenuto ai lettori di schermo.</p><p>${why.fix}Fornisci un attributo <code>title</code> o <code>aria-label</code> univoco.</p>`,
	EMBED_UNFOCUSABLE: `<p>Questo attributo indica a tastiera e tecnologie assistive di ignorare l’elemento. Rimuovi questo attributo a meno che l’iframe non contenga link, pulsanti, campi di form o contenuto scorrevole.</p>`,
	EMBED_VIDEO: `<p>Questo controllo non è in grado di “vedere” se i video hanno sottotitoli, né se qualcuno li ha revisionati, quindi è necessaria una verifica manuale.</p><p>${why.fix}Assicurati che siano disponibili <a href="https://www.w3.org/WAI/media/av/captions/">sottotitoli accurati (“CC”)</a>, e verifica che i parlanti e gli effetti sonori significativi siano identificati correttamente.</p>`,
	HEADING_EMPTY: `<p>Le intestazioni vuote creano vuoti fuorvianti nella struttura della pagina.</p><p>${why.fix}Aggiungi testo a questa intestazione, oppure elimina questa riga vuota.</p>${why.headings}`,
	HEADING_UNPRONOUNCEABLE: `<p>Le intestazioni vuote creano vuoti fuorvianti nella struttura della pagina.</p><p>${why.fix}Aggiungi testo leggibile a questa intestazione, oppure convertila in un paragrafo.</p>${why.headings}`,
	HEADING_EMPTY_WITH_IMAGE: `<p>Le intestazioni vuote creano vuoti fuorvianti nella struttura della pagina.</p><p>${why.fix}Se non è un’intestazione, cambiane il formato da <code>Intestazione %(level)</code> a <code>Paragrafo</code>. Altrimenti, inserisci il significato dell’immagine nel suo testo alternativo.</p>${why.headings}`,
	HEADING_FIRST: `${why.fix}Assicurati che il titolo della pagina sia contrassegnato come Intestazione 1 o Intestazione 2. ${why.headings}`,
	HEADING_LONG: `<p>${why.fix}A meno che questa intestazione non sia un riferimento fisso come il titolo di un articolo pubblicato, accorciala per agevolare la lettura veloce:<span hidden>%(drop)%(drop)</span></p><p><i>%(TEXT)</i></p>${why.headings}`,
	HEADING_MISSING_ONE: `<p>${why.fix}Contrassegna il titolo della pagina come intestazione di livello 1, per indicare l’inizio della struttura del documento.</p>${why.headings}`,
	HEADING_SKIPPED_LEVEL: `<p>Questa intestazione passa dal <code>livello %(prevLevel)</code> al <code>livello %(level)</code>. Con un lettore di schermo, sembra che manchi del contenuto.</p><p>${why.fix}Regola i livelli per formare una struttura accurata, senza salti.</p>${why.headings}`,
	HIDDEN_FOCUSABLE: `<p>Questo elemento interattivo ha un attributo <code>aria-hidden=&quot;true&quot;</code>, ma può ancora ricevere il focus da tastiera.</p><p>${why.fix}Se <strong>intendi</strong> nascondere questo elemento ai lettori di schermo, devi anche aggiungere <code>tabindex=&quot;-1&quot;</code>. Altrimenti, rimuovi l’attributo <code>aria-hidden=&quot;true&quot;</code>.</p><p><strong>Elemento:</strong> <code>%(ELEMENT)</code></p>`,
	IMAGE_ALT_TOO_LONG: `<p>Questo testo alternativo è lungo %(altLength) caratteri: <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Riassumi il testo, oppure sposta parte della descrizione in una didascalia.</p><div class="why"><p>Suggerimento: le immagini complesse che trasmettono più informazioni di quante ne stiano in una frase richiedono di solito una didascalia o un’alternativa <strong>visibile</strong> che descriva o interpreti i dettagli principali. È corretto rimandare gli utenti di lettori di schermo a tale testo:</p><ul><li>“Locandina della festa da ballo di venerdì; dettagli nella didascalia.”</li> <li>“Grafico che mostra un calo dei problemi del 10% quest’anno; dettagli nella tabella.”</li></ul></div>`,
	IMAGE_DECORATIVE: `<p>Questa immagine è stata nascosta ai lettori di schermo con un testo alternativo vuoto. Solo le immagini prive di significato, come icone ridondanti e texture di sfondo, dovrebbero essere nascoste in questo modo.</p><p>${why.fix}Se questa immagine aggiunge valore alla pagina, fornisci un testo alternativo.</p>${why.images}`,
	IMAGE_DECORATIVE_CAROUSEL: `L’immagine è contrassegnata come <strong>decorativa</strong>, ma tutte le immagini di un carosello o di una galleria dovrebbero includere un testo alternativo descrittivo, per garantire a tutti un’esperienza equivalente.`,
	IMAGE_FIGURE_DECORATIVE: `<p>Questa immagine verrà ignorata dalle tecnologie assistive. La sua didascalia avrà senso senza l’immagine?</p><p>${why.fix}Se la didascalia non descrive il significato visivo dell’immagine, fornisci un testo alternativo per ciò che la didascalia non descrive.</p><div class="why"><p>Suggerimento: immagini, testi alternativi e didascalie lavorano insieme:</p><ul><li>Le didascalie visibili forniscono contesto e interpretazione per un’immagine.</li><li>I testi alternativi invisibili descrivono l’immagine per chi non può vederla, così da sapere che cosa sta descrivendo la didascalia.</li></ul></div>`,
	IMAGE_FIGURE_DUPLICATE_ALT: `<p><strong>Testo duplicato: </strong><i>%(ALT_TEXT)</i></p><p>${why.fix}Descrivi nel testo alternativo ogni significato visivo mancante.</p><div class="why"><p>Suggerimento: immagini, testi alternativi e didascalie lavorano insieme:</p><ul><li>Le didascalie visibili forniscono contesto e interpretazione per un’immagine.</li><li>I testi alternativi invisibili descrivono l’immagine per chi non può vederla, così da sapere di che cosa sta parlando la didascalia.</li></ul></div>`,
	LABELS_ARIA_LABEL_INPUT: `<p><strong>Etichetta invisibile del campo:</strong> <i>%(TEXT)</i></p><p>Verifica che ci sia un’etichetta visibile del campo, che resti visibile quando il campo contiene testo e che corrisponda all’etichetta invisibile del campo.</p><div class="why"><p>Se i campi sono etichettati solo con un titolo o un segnaposto, l’etichetta scompare visivamente non appena si inizia a scrivere. Questo rende difficile rivedere i dati inseriti quando ci sono più campi. Inoltre è facile dimenticare di aggiornare l’etichetta invisibile del campo.</p></div>`,
	LABELS_INPUT_RESET: `<p>I pulsanti di reset sono facili da attivare per errore e causano la perdita dei dati senza possibilità di annullare.</p><p>${why.fix}A meno che non reimposti un singolo campo, valuta di rimuoverlo o di offrire un modo per annullare prima di eseguire l’azione.</p>`,
	LABELS_MISSING_IMAGE_INPUT: `Al pulsante immagine manca il testo alternativo. Aggiungi un testo alternativo per fornire un nome accessibile. Ad esempio: <em>Cerca</em> o <em>Invia</em>.`,
	LABELS_MISSING_LABEL: `<p>${why.fix}Aggiungi un <code>id</code> a questo campo e un attributo <code>for</code> corrispondente all’etichetta.</p>`,
	LABELS_NO_FOR_ATTRIBUTE: `Non c’è alcuna etichetta associata a questo campo. Aggiungi all’etichetta un attributo <code>for</code> che corrisponda all’<code>id</code> di questo campo. <hr> <strong>ID:</strong> <code>#%(ID)</code>`,
	LABELS_PLACEHOLDER: `<p>Il testo segnaposto può essere scambiato per contenuto già inserito se ha un buon contrasto, oppure risultare illeggibile se non lo ha. Inoltre scompare durante l’inserimento, eliminando informazioni di cui gli utenti potrebbero avere bisogno per verificare eventuali errori.</p><p>${why.fix}Assicurati che le informazioni chiave, come l’etichetta del campo, il testo di aiuto e le istruzioni sul formato, restino visibili quando il campo contiene del testo, e valuta di eliminare del tutto il segnaposto.</p>`,
	LABEL_IN_NAME: `<p><strong>Testo visibile:</strong> <i>%(VISIBLE)</i></p><p><strong>Etichetta per i lettori di schermo:</strong> <i>%(LABEL)</i></p><p>Il testo visibile di questo elemento sembra diverso dal nome accessibile. Questo può confondere gli utenti di lettori di schermo e compromettere il controllo vocale.</p><p>${why.fix}Assicurati che l’etichetta visibile inizi con il testo dell’etichetta invisibile e non contenga informazioni significative che manchino nell’etichetta invisibile.</p>`,
	LINK_ALT_FILE_EXT: `<p>Questo testo alternativo è probabilmente un nome file anziché un’etichetta significativa per un link:<br><span hidden>%(ALT)</span><i>%(alt)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p><div class="why"> <p>Lo scopo del testo alternativo è fornire un’alternativa a ciò che un’immagine significa, non a ciò che contiene. Il significato di un’immagine linkata è la destinazione del link:</p><ul><li>“Pagina con testo scritto” descrive l’immagine, non un link.</li><li>“IMG_1234.jpg” è solo un nome file.</li><li>“Modulo di iscrizione all’evento (.doc)” è la destinazione di un link.</li></ul></div>`,
	LINK_ALT_MAYBE_BAD: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_ALT_MAYBE_BAD_WARNING: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_ALT_UNPRONOUNCEABLE: `<p>Il testo alternativo di questa immagine linkata contiene solo simboli e/o spazi non pronunciabili: <i>%(ALT_TEXT)</i></p><p>I lettori di schermo annunceranno che c’è un link, ma non saranno in grado di descriverlo.</p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_CLICK_HERE: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Rimuovi le parole ridondanti che distolgono l’attenzione dallo scopo del link.</p>${why.links}`,
	LINK_DOI: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Inserisci il link sul titolo dell’articolo e indica il numero DOI come testo semplice, invece di inserire il link sul numero DOI e lasciare il titolo dell’articolo come testo semplice.</p><div class="why"><p>La <a href="https://apastyle.apa.org/style-grammar-guidelines/paper-format/accessibility/urls#:~:text=descriptive%20links">guida di stile APA</a> raccomanda di usare link descrittivi sui siti web, perché gli utenti scorrono la pagina leggendo i link e usano la ricerca nella pagina per trovare i link per nome. È molto più probabile che notino gli articoli di loro interesse quando il link è sul titolo.</p><p>Questo permette inoltre ai lettori di schermo di descrivere ogni link in modo significativo, invece di pronunciare una sequenza di numeri priva di significato.</p></div>`,
	LINK_EMPTY: `<p>${why.fix}Aggiungi testo che descriva la sua destinazione, oppure eliminalo se è solo un errore di battitura o uno spazio linkato.</p><div class="why"><p>Suggerimento: i lettori di schermo non possono descrivere i link che contengono solo spazi o simboli. Rimangono silenziosi (“Link, [...pausa imbarazzante dove dovrebbe essere il titolo del link...]”), oppure leggono l’URL: “Link, H-T-T-P-S barra barra esempio punto com.”</p><p>Nota: in alcuni editor di contenuti gli spazi linkati possono essere difficili da eliminare; a volte è necessario eliminare “a cavallo” dello spazio, cancellando e riscrivendo le parole su entrambi i lati di uno spazio linkato.</p></div>`,
	LINK_EMPTY_LABELLEDBY: `<p>Questo link ha un attributo <code>aria-labelledby</code> che non corrisponde all’<code>ID</code> di alcun elemento della pagina.</p><p>${why.fix}Fornisci un <code>ID</code> valido, oppure rimuovi questo attributo e descrivi il link in un altro modo.</p>`,
	LINK_EMPTY_NO_LABEL: `<p>${why.fix}Aggiungi testo che descriva la sua destinazione, oppure eliminalo se è solo un errore di battitura, come uno spazio linkato.</p><div class="why"><p>Suggerimento: i lettori di schermo non possono descrivere i link vuoti. Rimangono in silenzio (“Link, [...pausa imbarazzante dove dovrebbe essere il titolo del link...]”), oppure leggono l’URL: “Link, H-T-T-P-S barra barra esempio punto com.”</p><p>Nota: in alcuni editor di contenuti gli spazi linkati possono essere difficili da eliminare; a volte è necessario eliminare “a cavallo” dello spazio, cancellando e riscrivendo le parole su entrambi i lati di uno spazio linkato.</p></div>`,
	LINK_UNPRONOUNCEABLE: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Aggiungi testo o un titolo che descriva la sua destinazione, oppure eliminalo se è solo un errore di battitura o uno spazio linkato.</p><div class="why"><p>Suggerimento: i lettori di schermo non possono descrivere i link che contengono solo spazi o simboli. Rimangono silenziosi (“Link, [...pausa imbarazzante dove dovrebbe essere il titolo del link...]”), oppure leggono il nome del simbolo.</p></div>`,
	LINK_FILE_EXT: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>Questo link punta a un PDF o a un file scaricabile (ad es. MP3, Zip, documento Word) senza avvisare.</p><p>${why.fix}Usa un testo o un’icona per <a href="https://itmaybejj.github.io/linkpurpose/">indicare il tipo di file</a> nel testo del link.</p><p class="why">Per i file di grandi dimensioni, valuta di indicare anche la dimensione. Ad esempio: “Relazione esecutiva (PDF, 3 MB)”.</p>`,
	LINK_IDENTICAL_NAME: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Riformula i link che portano a pagine diverse usando i titoli univoci delle rispettive destinazioni.</p>${why.links}`,
	LINK_IMAGE_ALT: `<p><strong>Testo alternativo:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_IMAGE_ALT_AND_TEXT: `<p><strong>Testo alternativo:</strong> <i>%(ALT_TEXT)</i></p><p><strong>Testo del link incluso il testo alternativo:</strong> <i>%(TEXT)</i></p><p>${why.fix}Modifica o rimuovi il testo alternativo se aggiunge informazioni irrilevanti o ridondanti.</p>${why.imageLinks}`,
	LINK_IMAGE_LONG_ALT: `<p>Questo testo alternativo è lungo %(altLength) caratteri: <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p><div class="why"><p>Gli utenti di lettori di schermo ascoltano spesso un elenco dei link della pagina, fuori contesto. Poiché in questo elenco il testo alternativo di un’immagine linkata diventa il titolo del link, dovrebbe <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">descrivere la destinazione del link</a>, non il contenuto dell’immagine.</p></div>`,
	LINK_IMAGE_NO_ALT_TEXT: `<p>Quando un link racchiude un’immagine, il testo alternativo dell’immagine <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">fornisce il titolo del link ai lettori di schermo</a>.</p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_IMAGE_TEXT: 'L’immagine è contrassegnata come decorativa, anche se il link usa il testo circostante come etichetta descrittiva.',
	LINK_MAYBE_BUTTON: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>Questo link ha una destinazione non valida e un nome che suggerisce possa funzionare come un pulsante o un interruttore invece che come link.</p><p>${why.fix}Usa invece un <a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/">&lt;button&gt;</a>, oppure correggi la destinazione del link.</p><div class="why"><p>Suggerimento: le tecnologie assistive trattano pulsanti e link in modo diverso. Usare l’elemento HTML corretto garantisce che gli utenti sappiano quali scorciatoie da tastiera utilizzare e quale azione verrà attivata.</p></div>`,
	LINK_NEW_TAB: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Imposta questo link in modo che si apra nella stessa scheda, oppure <a href="https://itmaybejj.github.io/linkpurpose/">avvisa prima gli utenti</a>.</p><div class="why"><p>Chi legge può sempre <em>scegliere</em> di aprire un link in una nuova scheda. Quando un link forza l’apertura di una nuova scheda, spesso risulta confuso o fastidioso, soprattutto per gli utenti di tecnologie assistive, che si chiedono perché il pulsante “Indietro” del browser abbia smesso di funzionare.</p><p>Nota: i moduli sono l’eccezione. Quando l’utente sta compilando un modulo, aprire un link nella stessa finestra potrebbe fargli perdere il lavoro svolto, per cui i link all’interno dei moduli di solito si aprono in nuove schede.</p></div>`,
	LINK_PLACEHOLDER_ALT: `<p><strong>Testo alternativo:</strong> <i>%(alt)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_STOPWORD: `<p>Testo del link: <i>%(ERROR)</i></p><p>${why.fix}Usa un testo che descriva chiaramente la destinazione.</p>${why.links}`,
	LINK_STOPWORD_ARIA: `<p>È stato fornito un nome diverso tramite ARIA:</p><p><strong>Testo visibile:</strong> <i>%(VISIBLE)</i></p><p><strong>Testo nascosto:</strong> <i>%(HIDDEN)</i></p><p>${why.fix}Scrivi link significativi per tutti, non solo per gli utenti dei lettori di schermo, e assicurati che l’<a href="https://www.w3.org/WAI/WCAG22/Understanding/label-in-name.html">etichetta visibile di ciascun elemento corrisponda al suo nome</a>, così che chi usa il controllo vocale possa indicare al proprio browser quale link cliccare.</p>${why.links}`,
	LINK_SUS_ALT: `<p>A meno che “<i>%(alt)</i>” non descriva la destinazione del link, questo alt probabilmente descrive l’immagine.</p><p><strong>Testo alternativo:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Usa il titolo della destinazione del link come testo alternativo per le immagini linkate.</p>${why.imageLinks}`,
	LINK_SYMBOLS: `<p>Simbolo trovato: <i>%(ERROR)</i></p><p>${why.fix}Evita di usare simboli come inviti all’azione nel testo dei link, a meno che non siano nascosti alle tecnologie assistive. I lettori di schermo potrebbero leggere i simboli ad alta voce, creando confusione.</p>`,
	LINK_URL: `<p><strong>Testo del link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Sostituisci il testo di questo link con il titolo della sua destinazione o del suo scopo.</p><div class="why"><p>Suggerimento: chi legge scorre la pagina cercando i link per nome. Questo vale soprattutto per gli utenti di lettori di schermo, che navigano e cercano usando un elenco dei link presenti nella pagina.</p><p>Gli URL usati come link non si possono scorrere a colpo d’occhio né trovare con la ricerca nella pagina, quindi è meno probabile che le persone li trovino e li clicchino.</p></div>`,
	META_LANG: `<p>${why.fix}Aggiungi un <a href="https://www.w3.org/International/questions/qa-html-language-declarations">attributo di lingua al tag HTML della pagina</a>.</p><div class="why"><p>Suggerimento: i lettori di schermo pronunciano le parole in base ai tag di lingua. Pronunciare una lingua con il pacchetto vocale sbagliato produce un parlato incomprensibile. Se la lingua non è indicata, il lettore di schermo userà la lingua predefinita del browser o proverà a indovinarla, con risultati imprevedibili.</p></div>`,
	META_LANG_VALID: `<p><strong>Elemento:</strong> <code>&lt;%(ELEMENT) lang="%(CODE)"&gt;</code></p><p>${why.fix}Sostituisci l’attributo lang con un codice lingua valido.</p><div class="why"><p>Suggerimento: le pagine e gli elementi hanno <a href="https://www.w3.org/International/questions/qa-html-language-declarations">attributi di lingua</a> affinché i lettori di schermo e gli strumenti di traduzione leggano correttamente il testo.</p></div>`,
	META_MAX: `<p>Questo meta tag limita quanto gli utenti possono ingrandire il testo.</p><p>${why.fix}Rimuovi o modifica il parametro per consentire l’ingrandimento completo.</p>`,
	META_REFRESH: `<p>Le pagine non dovrebbero aggiornarsi automaticamente tramite un meta tag. L’aggiornamento interrompe l’utente senza preavviso né possibilità di impedirlo, gli fa perdere il punto in cui stava leggendo e può azzerare i dati già inseriti nei moduli.</p><p>${why.fix}Per aggiornare il contenuto della stessa pagina, usa AJAX per aggiornare le sezioni senza ricaricare la pagina, oppure usa JavaScript per avviare il ricaricamento, così che l’utente possa essere avvisato prima e abbia la possibilità di rimandarlo.</p>`,
	META_SCALABLE: `<p>Questo meta tag impedisce agli utenti di ingrandire il testo.</p><p>${why.fix}Rimuovi o modifica il parametro per consentire l’ingrandimento.</p>`,
	META_TITLE: `<p>${why.fix}Aggiungi un tag <code>&lt;title&gt;</code> all’elemento <code>head</code> della pagina.</p><div class="why"><p>Suggerimento: molti aspetti della navigazione dipendono da un <a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/title">tag title breve e univoco</a>:</p><ul><li>I motori di ricerca lo usano come titolo dei risultati.</li><li>I browser lo usano come titolo delle schede.</li><li>I lettori di schermo lo pronunciano quando si cambia scheda.</li></ul><p>Senza un titolo della pagina, le persone vedono o sentono un URL grezzo.</p></div>`,
	MISSING_ALT: `<p>Quando i lettori di schermo incontrano un’immagine senza alcun attributo alt, provano invece a pronunciare l’URL del file dell’immagine, spesso una lettera alla volta.</p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p>${why.images}`,
	MISSING_ALT_LINK: `<p>Quando i lettori di schermo incontrano un’immagine senza alcun attributo alt, provano invece a pronunciare l’URL del file dell’immagine, spesso una lettera alla volta. Questo è un problema soprattutto per le immagini linkate.</p><p>${why.fix}Aggiungi un testo alternativo che corrisponda alla destinazione del link.</p>${why.imageLinks}`,
	MISSING_ALT_LINK_HAS_TEXT: `<p>Questa immagine fa parte di un link con testo. Se il testo visibile è sufficiente a descrivere il link, aggiungi un alt vuoto (alt="") per indicare ai lettori di schermo di ignorare questa immagine. Altrimenti, aggiungi un alt che aiuti a descrivere la destinazione o lo scopo del link.</p>${why.imageLinks}`,
	QA_BAD_LINK: `<p>Il link sembra puntare a un ambiente di sviluppo:<br>{L} <code>%(LINK)</code></p><p>${why.fix}Usa un percorso relativo (/cartella) o l’URL pubblico.</p>`,
	QA_BLOCKQUOTE: `<p><strong>Citazione sospettosamente breve:</strong> <i>%(TEXT)</i></p><p>${why.fix}Se è un’intestazione e non una citazione, contrassegnala come intestazione così che appaia nella struttura della pagina.</p>${why.headings}`,
	QA_DOCUMENT: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>I documenti linkati sono considerati contenuti web e devono anch’essi essere accessibili. Verifica che in questo documento siano stati taggati le intestazioni, le intestazioni di tabella e i testi alternativi delle immagini.</p><div class="why"><ul><li>Rendi più accessibile il tuo <a href="https://support.google.com/docs/answer/6199477?hl=it">documento o la tua presentazione di Google Workspace.</a></li><li>Rendi più accessibili i tuoi <a href="https://support.microsoft.com/it-it/office/create-accessible-office-documents-868ecfcd-4f00-4224-b881-a65537a7c155">documenti di Office.</a></li></ul></div>`,
	QA_FAKE_HEADING: `<p><strong>Testo in grassetto:</strong> <i>%(TEXT)</i></p><p>${why.fix}Se questo testo è in grassetto per segnare un cambio di argomento, contrassegnalo come intestazione così che gli utenti dei lettori di schermo possano usarlo per navigare la pagina.</p><div class="why"> <p>Suggerimento: gli stili grassetto e corsivo forniscono enfasi visiva, ma non aggiungono automaticamente il testo al sommario del documento per le tecnologie assistive.</p></div>`,
	QA_FAKE_LIST: `<p>${why.fix}Se questo <i>%(TEXT)</i> fa parte di un elenco, sostituiscilo con la formattazione di elenco.</p><div class="why"><p>Suggerimento: la formattazione di elenco è strutturale, sia visivamente sia per la navigazione:</p> <ol><li>Gli elenchi allineano i rientri per facilitare la lettura.</li> <li>Gli elenchi sono leggibili dalle macchine. I lettori di schermo orientano gli utenti annunciando regolarmente la loro posizione nell’elenco (“elemento 3 di 7”).</li></ol> <p>&nbsp;&nbsp;&nbsp;3. Una frase preceduta da un numero come questa, invece, non fa rientrare la seconda riga quando va a capo e non viene inclusa nel conteggio degli elementi per gli utenti di lettori di schermo.</p></div> `,
	QA_IN_PAGE_LINK: `<p><strong>URL:</strong> <i>#%(ID)</i></p><p><strong>Link:</strong> <code>%(TEXT)</code></p><p>La destinazione del link non corrisponde ad alcun elemento di questa pagina.</p><div class="why"><p>Nota per gli sviluppatori: se non si tratta di un normale link e la destinazione è un segnaposto per un evento JavaScript, verifica che funzioni quando viene attivato con la tastiera prima di aggiungerlo all’elenco delle esclusioni del controllo.</p></div>`,
	QA_JUSTIFY: `<p>Il testo giustificato inserisce spazi aggiuntivi per allineare i paragrafi sia al margine sinistro sia a quello destro. Gli spazi irregolari da una riga all’altra rendono il testo più difficile da leggere per molte persone.</p><p>${why.fix}Usa il testo allineato a sinistra.</p>`,
	QA_NESTED_COMPONENTS: `Evita di annidare componenti di layout interattivi, ad esempio inserendo accordion all’interno di altri accordion, oppure schede all’interno di accordion e viceversa. Questo può complicare la navigazione, aumentare il sovraccarico cognitivo e portare le persone a non notare dei contenuti.`,
	QA_PDF: `<p><strong>Link:</strong> <i>%(TEXT)</i></p><p>${why.fix}Esegui una delle seguenti azioni:</p><ul><li>inserisci invece un link a una pagina web,</li><li>inserisci <em>anche</em> un link a una pagina web o a un documento modificabile, così che questo PDF sia solo l’opzione “stampabile”, oppure</li><li>come minimo, assicurati che questo PDF sia leggibile con i lettori di schermo <a href='https://webaim.org/techniques/acrobat/' target='_blank'>verificando manualmente che sia stato taggato</a> con intestazioni, ordine di lettura delle colonne, intestazioni di tabella e testo alternativo.</li>	</ul>	<div class="why"><p>Suggerimento: gli utenti di dispositivi mobili e di tecnologie assistive preferiscono quasi sempre le pagine web ai PDF. I PDF non si adattano ai dispositivi mobili e spesso sono privi dei tag necessari per navigarne il testo con i lettori di schermo.</p></div>`,
	QA_SMALL_TEXT: `<p><strong>Testo:</strong> <i>%(TEXT)</i></p><p>${why.fix}Mantieni la dimensione almeno all’80% di quella predefinita. Il testo piccolo è difficile da leggere, in particolare per chi ha ipovisione.</p>`,
	QA_STRONG_ITALICS: `<p><strong>Testo:</strong> <i>%(TEXT)</i></p><p>${why.fix}Riserva grassetto e corsivo a parole e frasi chiave.</p><div class="why"><p>Nota: se si tratta di una citazione, puoi usare il tag blockquote per distinguerla dal resto del testo.</p></div>`,
	QA_SUBSCRIPT: `<p><strong>Testo:</strong> <i>%(TEXT)</i></p><p>La formattazione in pedice e in apice rende il testo troppo piccolo per essere letto facilmente da molte persone. Dovrebbe essere usata solo per singole parole o espressioni, come numeri ordinali (4<sup>o</sup>), formule chimiche (H<sub>2</sub>O) e rimandi alle note a piè di pagina.</p>`,
	QA_UNDERLINE: `<p>Sul web il testo sottolineato si usa per i link, non per l’enfasi. Gli utenti penseranno di poterlo cliccare: <i><u>%(TEXT)</u></i></p><p>${why.fix}Usa il <strong>grassetto</strong> o il <em>corsivo</em> per l’enfasi, e le intestazioni per la struttura.</p><div class="why"><p>Nota: i lettori di schermo non annunciano la formattazione puramente visiva come la sottolineatura. Solo le intestazioni aggiungono testo alla struttura della pagina.</p></div>`,
	QA_UPPERCASE: `<p><strong>Testo:</strong> <i>%(TEXT)</i></p><p>${why.fix}Metti in maiuscolo solo poche parole per dare enfasi. BLOCCHI ESTESI DI TESTO IN MAIUSCOLO SONO PIÙ DIFFICILI DA LEGGERE E MOLTI LETTORI LI INTERPRETANO COME URLA.</p><div class="why"><p>Nota: i lettori di schermo non annunciano la formattazione puramente visiva come il testo in maiuscolo. Usa uno stile di intestazione se questo testo enfatizzato introduce un cambio di argomento o contenuto di importanza critica.</p></div>`,
	SUS_ALT: `<p>Il testo alternativo di questa immagine contiene la parola “<i>%(alt)</i>”. I lettori di schermo annunciano già che stanno descrivendo un’immagine quando leggono il testo alternativo, quindi frasi come “immagine di” e “foto di” sono generalmente ridondanti.</p><p><strong>Testo alternativo:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Descrivi in modo conciso cosa significa questa immagine, in questo contesto.</p><div class="why"><p>Suggerimento: queste frasi vale la pena mantenerle se il formato stesso è significativo:<br>“Una foto di un gatto, incorniciata e appesa al muro.”</p></div>`,
	TABINDEX_ATTR: `<p>Valori di tabindex maggiori di 0 spostano gli elementi focalizzabili al di fuori del loro ordine visivo, rendendo difficile agli utenti di tecnologie assistive individuarli e usarli.</p><p>${why.fix}Modifica invece l’ordine degli elementi nell’HTML, così che l’ordine di focus e l’ordine di lettura coincidano.</p><div class="why"><p>Suggerimento: l’ordine visivo delle parole sulla pagina e l’ordine con cui la tastiera scorre gli elementi sono solitamente gli stessi.</p><p>Assegnare un tabindex positivo a un elemento lo sposta all’inizio dell’ordine di tab, <strong>ma non dell’ordine visivo o di lettura</strong>.</p></div>`,
	TABLES_EMPTY_HEADING: `<p>${why.fix}Assicurati che ogni cella di intestazione contenga testo.</p><div class="why"><p>Suggerimento: i lettori di schermo usano le intestazioni di tabella per orientare gli utenti mentre esplorano una tabella. L’intestazione di tabella pertinente viene ripetuta quando il cursore entra in ciascuna colonna o riga.</p></div>`,
	TABLES_INVALID_HEADERS_REF: `<p>Questa tabella sta tentando di associare una specifica cella di dati a una specifica cella di intestazione, ma l’ID della cella di intestazione non è stato trovato: <code>%(VALUE)</code>.</p><p>${why.fix}Assicurati che ogni attributo <code>headers</code> corrisponda all’ID di una cella di intestazione della stessa tabella.</p><div class="why">Suggerimento: <a href="https://www.w3.org/WAI/WCAG22/Techniques/html/H43">l’uso di riferimenti manuali tramite ID</a> per associare celle di dati a celle di intestazione è complesso e fragile. Quando possibile, suddividi i dati complessi in tabelle più piccole con semplici righe e colonne di intestazione.</div>`,
	TABLES_MISSING_HEADINGS: `<p>${why.fix}Modifica le proprietà della tabella e specifica se le intestazioni di tabella si trovano nella prima riga, nella prima colonna o in entrambe.</p><div class="why"> <p>Suggerimento: i lettori di schermo usano le intestazioni di tabella per orientare gli utenti mentre esplorano una tabella. L’intestazione di tabella pertinente viene ripetuta quando il cursore entra in ciascuna colonna o riga.</p><p>Se questa tabella non ha intestazioni di tabella perché è usata solo per l’impaginazione visiva, rimuovi la formattazione della tabella e usa invece una formattazione a colonne puramente visiva.</p></div> `,
	TABLES_SEMANTIC_HEADING: `<p>${why.fix}Rimuovi questa formattazione da intestazione (h2, h3). Usa invece righe e colonne di intestazione. Se ti servono più righe di intestazione, dividi il contenuto in più tabelle.</p><div class="why"> <p>Suggerimento: le intestazioni di tabella sono direzionali: valgono per una sola riga o colonna. Le intestazioni di contenuto etichettano tutto il testo che segue, anche in colonne non correlate:</p><table><tr><th>1</th><th>2</th><th>3</th><td rowspan="2">Un’<strong>intestazione di tabella</strong> nella cella 2 etichetta la cella B. <br><br> Un’<strong>intestazione di contenuto</strong> nella cella 2 etichetta le celle 3, A, B e C, oltre a questo testo e al piè di pagina di questo tooltip.</td></tr> <tr><td>A</td><td>B</td><td>C</td></tr></table> </div>`,
};

